/// <summary>
/// Extension of CustCollectionJourDP
/// </summary>
[ExtensionOf(classstr(CustCollectionJourDP))]
final class METCustCollectionJourDP_Extension
{

}

Method.Source:
    /// <summary>
    /// Populates the core fields on the <c>CustCollectionJourTmp</c> table buffer in preparation for insert.
    /// </summary>
    /// <param name="_custCollectionLetterJour">
    /// A <c>custCollectionLetterJour</c> table buffer.
    /// </param>
    /// <param name="_custTable">
    /// A <c>CustTable</c> buffer.
    /// </param>
    /// <param name="_custCollectionLetterTrans">
    /// A <c>CustCollectionLetterTrans</c> table buffer.
    /// </param>
    /// <param name="_formLetterRemarks">
    /// A <c>FormLetterRemarks</c> table buffer.
    /// </param>
    /// <param name="_taxSpec">
    /// A <c>TaxSpec</c> table buffer.
    /// </param>
    /// <param name="_postingsUntil">
    /// A Date parameter.
    /// </param>
    protected void populateCustCollectionJourTmp(
            CustCollectionLetterJour _custCollectionLetterJour,
            CustTable _custTable,
            CustCollectionLetterTrans _custCollectionLetterTrans,
            FormLetterRemarks _formLetterRemarks,
            TaxSpec _taxSpec,
            TransDate _postingsUntil)
    {
        next populateCustCollectionJourTmp(
            _custCollectionLetterJour,
            _custTable,
            _custCollectionLetterTrans,
            _formLetterRemarks,
            _taxSpec,
            _postingsUntil);

        // MPJ_15096
        custCollectionJourTmp.METDataArea = companyInfo::find().DataArea;
        
        // TASK207962_CB897_IndustryKeyLimitedLogo - Begin
        METIndustryKey industryKey = METCustTable::find(_custCollectionLetterJour.AccountNum).IndustryKey;
        CustCollectionJourContract custCollectionJourContract = this.parmDataContract() as CustCollectionJourContract;
        SRSCatalogItemName reportNameLocal = custCollectionJourContract.parmMetcashReportName();

        if(reportNameLocal && industryKey)
        {
            container reportDesignNameContainer = SrsReportRunUtil::getReportAndDesignName(reportNameLocal);
            SysDocuBrandDetails docuBrandDetails = SysDocuBrandDetails::findByRepNameAndIndKey(conPeek(reportDesignNameContainer, 1), conPeek(reportDesignNameContainer, 2), industryKey);
            
            if (docuBrandDetails)
            {
                if (docuBrandDetails.METTaxRegNumber)
                {
                    custCollectionJourTmp.CompanyCoRegNum = docuBrandDetails.METTaxRegNumber;
                }
                if (docuBrandDetails.Image1Name)
                {
                    custCollectionJourTmp.CompanyLogo = SysDocuBrandImages::getImage(docuBrandDetails.Image1Name);
                    custCollectionJourTmp.PrintLogo   = true;
                }
                if (docuBrandDetails.Phone)
                {
                    custCollectionJourTmp.CompanyPhone = docuBrandDetails.Phone;
                }
                if (docuBrandDetails.TeleFax)
                {
                    custCollectionJourTmp.CompanyTeleFax = docuBrandDetails.TeleFax;
                }
            }
        }
        // TASK207962_CB897_IndustryKeyLimitedLogo - End
    
    }
